+    static byte[] Read(IntPtr handle, IntPtr address, int size) {
+        byte[] bytes = new byte[size]; IntPtr read;
+        if (!ReadProcessMemory(handle, address, bytes, size, out read) || read.ToInt64() != size) throw new Exception("inspection_unavailable");
+        return bytes;
+    }
+    static IntPtr Pointer(IntPtr handle, IntPtr address) { return new IntPtr(BitConverter.ToInt64(Read(handle, address, 8), 0)); }
+    public static Dictionary<string,string> Inspect(int pid) {
+        if (IntPtr.Size != 8) throw new Exception("inspection_unavailable");
+        IntPtr handle = OpenProcess(0x410, false, pid);
+        if (handle == IntPtr.Zero) throw new Exception("inspection_unavailable");
+        try {
+            BasicInfo info; int length;
+            if (NtQueryInformationProcess(handle, 0, out info, Marshal.SizeOf(typeof(BasicInfo)), out length) != 0) throw new Exception("inspection_unavailable");
+            IntPtr parameters = Pointer(handle, IntPtr.Add(info.Peb, 0x20));
+            IntPtr env = Pointer(handle, IntPtr.Add(parameters, 0x80));
+            var selected = new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
+            var names = new HashSet<string>(new [] {"APP_ENV", "APP_DEBUG", "AI_PROVIDER", "GEMINI_MODEL"}, StringComparer.OrdinalIgnoreCase);
+            var entry = new StringBuilder();
+            for (int offset=0; offset < 1024*1024; offset+=2) {
+                char ch = (char)BitConverter.ToUInt16(Read(handle, IntPtr.Add(env, offset), 2), 0);
+                if (ch != '\0') { entry.Append(ch); continue; }
+                if (entry.Length == 0) break;
+                string line = entry.ToString(); entry.Clear();
+                int equals = line.IndexOf('=');
